('025629', '268f80d3-e513-426d-a263-e45b5f70fde4', '194', 'Disability and Substance Abuse', 'Designed to provide an entry-level overview of disability under federal legislation and regulation, substance use and abuse among persons with disabilities as either a primary or secondary disability, the physical, psychological, and socio-cultural effects of drugs, and the impact substance abuse or dependence has on the capacity of individuals with disabilities to live independently, work, and otherwise engage in a full range of life activities.  ', 'None', 'C', 'RP & SE 121', 'REHABILITATION PSYCHOLOGY AND SPECIAL EDUCATION 121', 3, 3, NULL, NULL, 'S', NULL, NULL, NULL, NULL, NULL, 'E', 'Not Applicable', NULL, 'Student Option', 'N', 'N', 121, 0),
('002649', 'ac55d80e-a49c-41b6-abab-234b1cfd65ce', '186', 'Second Semester Asian Language', 'Proficiency at the elementary level in listening, speaking, reading and writing, using communicative approaches. Students with prior experience in the language are required to take a placement test administered by the department. Not open to students with credit for LCA LANG 302 prior to Fall 2019.', 'ASIALANG 121 (or LCA LANG 301 prior to Fall 2019)', 'C', 'ASIALANG 122', 'ASIAN LANGUAGES AND CULTURES: LANGUAGES 122', 4, 4, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'E', 'Occasionally', NULL, 'Student Option', 'N', 'Y', 122, 2),
