('004102.51', '2c74c344-8bad-4da0-9db1-622017d204aa', '260', 'Early Black Feminisms', 'Introduction to the critical study of specific literary forms (e.g., comedy, short story) and the connections between literary forms and other cultural and artistic phenomena (e.g., cinema, TV, music, visual arts). ', 'None', 'C', 'COMP LIT 203', 'COMPARATIVE LITERATURE 203', 3, 3, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'L', 'E', 'Fall, Spring, Summer', NULL, 'Student Option', 'N', 'Y', 203, 2),
('004102', '5cb3f229-b2a2-43e7-918b-1bd152ebd90c', '260', 'Introduction to Cross-Cultural Literary Forms', 'Introduction to the critical study of specific literary forms (e.g., comedy, short story) and the connections between literary forms and other cultural and artistic phenomena (e.g., cinema, TV, music, visual arts). ', 'None', 'C', 'COMP LIT 203', 'COMPARATIVE LITERATURE 203', 3, 3, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'L', 'E', 'Fall, Spring, Summer', NULL, 'Student Option', 'N', 'Y', 203, 2),
('004102.55', '01894437-410d-4d5e-9f6a-f948add83cee', '260', 'Tragedy', 'Introduction to the critical study of specific literary forms (e.g., comedy, short story) and the connections between literary forms and other cultural and artistic phenomena (e.g., cinema, TV, music, visual arts). ', 'None', 'C', 'COMP LIT 203', 'COMPARATIVE LITERATURE 203', 3, 3, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'L', 'E', 'Fall, Spring, Summer', NULL, 'Student Option', 'N', 'Y', 203, 0),
('026549', 'eab99f13-d41d-4cb1-9825-5a52448c99c6', '310', 'Internship in Education, Arts, or Health', 'Provides the opportunity to reflect and critically analyze workplace experience in the field of education, arts, and/or health and enhance career opportunities through the exposure to the nexus of career development theory and practice.', 'None', NULL, 'ED POL 203', 'EDUCATIONAL POLICY STUDIES 203', 1, 3, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'Not Applicable', 'Workplace Experience Course', 'Student Option', 'N', 'Y', 203, 2),
